INSERT INTO `competition_rules` (`status`, `sort`, `is_deleted`, `category_key`, `title`, `summary`, `content`, `cover_image`, `source_url`, `published_at`, `create_at`, `update_at`) VALUES
(1, 10, 0, 'college', '机器人擂台赛规则', '全国高校组机器人擂台对抗赛竞赛规则，含场地规格、评分标准与器材要求。', '<h2>一、竞赛目标</h2><p>机器人擂台赛旨在考察参赛队伍在机器人结构设计、运动控制与对抗策略方面的综合能力。参赛机器人需在限定场地内将对手推下擂台或使其失去行动能力。</p><h2>二、场地规格</h2><p>擂台为直径 150cm 的圆形平台，表面铺设防滑材质，边缘设置 5cm 高的护栏。擂台中心有直径 30cm 的起始区标识。</p><h2>三、参赛组别</h2><ul><li><strong>本科组</strong>：全日制普通本科院校在校生</li><li><strong>高职组</strong>：高等职业院校在校生</li><li><strong>中学组</strong>：普通高中、中职院校在校生</li></ul><h2>四、评分标准</h2><table><tr><th>评分项</th><th>分值</th><th>说明</th></tr><tr><td>对抗胜利</td><td>60分</td><td>将对手推下擂台或使其停止运动</td></tr><tr><td>技术创新</td><td>20分</td><td>结构设计、传感器应用的创新性</td></tr><tr><td>现场表现</td><td>20分</td><td>稳定性、完成比赛的用时</td></tr></table><h2>五、注意事项</h2><p>1. 机器人总重量不得超过 3kg（含电池）。</p><p>2. 禁止使用任何可能对场地或其他机器人造成永久性损坏的装置。</p><p>3. 比赛过程中严禁人工干预。</p>', '__ROOT__/static/index/images/events/event-01.jpg', '', '2025-03-15 10:00:00', NOW(), NOW()),
(1, 9, 0, 'college,vocational,middle', '智能搬运赛规则', '智能搬运赛要求机器人自主完成物品识别、路径规划与精准搬运任务。', '<h2>一、竞赛目标</h2><p>智能搬运赛模拟工业物流场景，要求机器人在规定时间内完成货物的识别、抓取与搬运任务，考察机器视觉、运动规划与机械控制综合能力。</p><h2>二、竞赛场地</h2><p>场地尺寸为 240cm × 180cm，设有起点区、货物存放区（A/B/C 三个颜色编码区域）和目的地区。地面设有黑色循迹线。</p><h2>三、任务流程</h3><ol><li>机器人从起点区出发，沿循迹线行驶至货物存放区</li><li>通过视觉识别系统识别目标货物颜色与形状</li><li>使用机械臂或抓取装置拾取目标货物</li><li>将货物搬运至对应颜色的目的地区</li><li>返回起点区，完成全部搬运任务</li></ol><h2>四、评分细则</h2><table><tr><th>评分项</th><th>分值</th></tr><tr><td>正确识别货物</td><td>20分</td></tr><tr><td>成功抓取货物</td><td>20分</td></tr><tr><td>搬运至正确区域</td><td>30分</td></tr><tr><td>完成用时</td><td>20分</td></tr><tr><td>现场答辩</td><td>10分</td></tr></table>', '__ROOT__/static/index/images/events/event-02.jpg', '', '2025-03-10 14:30:00', NOW(), NOW()),
(1, 8, 0, 'college,vocational', '智能消防赛规则', '模拟真实消防场景，机器人在复杂环境中完成火源探测与灭火任务。', '<h2>一、竞赛简介</h2><p>智能消防赛模拟建筑物内的火灾场景，要求参赛机器人自主完成环境探索、火源探测、路径规划与灭火操作，重点考察机器人在复杂环境中的感知与决策能力。</p><h2>二、场地说明</h2><p>场地为 300cm × 300cm 的迷宫式房间布局，包含客厅、卧室、走廊等功能区域。区域内随机放置模拟火源（红色LED灯）与干扰物（橙色/黄色LED灯）。</p><h2>三、任务要求</h2><ul><li>机器人需在 5 分钟内自主探索全部房间区域</li><li>准确识别真正的火源（排除干扰物）</li><li>使用喷水或气体灭火装置扑灭火焰</li><li>返回安全出口位置并发出警报信号</li></ul><h2>四、器材限制</h2><p>机器人尺寸不超过 30cm × 30cm × 30cm，重量不超过 5kg。灭火介质仅限清水或压缩二氧化碳，禁止使用化学灭火剂。</p><h2>五、评分标准</h2><p>总分 100 分：环境探索覆盖率 25 分、火源识别准确率 30 分、灭火成功率 25 分、返回出口 20 分。</p>', '__ROOT__/static/index/images/events/event-03.jpg', '', '2025-03-05 09:00:00', NOW(), NOW()),
(1, 7, 0, 'college,vocational', '智能服务机器人规则', '面向服务场景的人机交互与多任务执行能力竞赛。', '<h2>一、竞赛目标</h2><p>智能服务机器人赛项模拟酒店/医院服务场景，要求机器人完成迎宾引导、物品递送、语音交互等多项服务任务，考察多传感器融合与人机协作能力。</p><h2>二、竞赛场景</h2><p>模拟酒店大堂场景，包含前台、电梯口、三个客房区域。机器人需识别客人的语音指令，完成房间引导、行李递送、信息查询等服务。</p><h2>三、评分维度</h2><table><tr><th>维度</th><th>分值</th><th>考核要点</th></tr><tr><td>语音交互</td><td>25分</td><td>语音识别准确率、自然语言理解、多轮对话</td></tr><tr><td>导航避障</td><td>25分</td><td>路径规划效率、动态避障能力</td></tr><tr><td>任务执行</td><td>30分</td><td>递送准确性、操作稳定性</td></tr><tr><td>创新设计</td><td>20分</td><td>结构创新、算法创新、交互创新</td></tr></table><h2>四、技术规范</h2><p>机器人高度 80-120cm，底盘直径不超过 40cm，需具备语音输入输出、视觉识别、自主导航等基本能力。</p>', '__ROOT__/static/index/images/events/event-04.jpg', '', '2025-02-28 16:00:00', NOW(), NOW()),
(1, 6, 0, 'vocational', '搬运码垛赛规则', '工业级码垛与搬运任务训练，对接智能制造产业需求。', '<h2>一、竞赛目标</h2><p>搬运码垛赛模拟现代工业物流中心的自动化码垛作业，要求机器人完成箱体的识别、抓取、搬运与堆叠任务，考察机械臂控制精度与路径优化能力。</p><h2>二、竞赛场地</h2><p>场地为 200cm × 150cm 的工位区域，设有来料传送带（模拟）、码垛托盘（标准 60cm × 40cm 木托盘）和空箱暂存区。</p><h2>三、任务流程</h2><ol><li>从来料区识别箱体规格（大/中/小三种）</li><li>使用机械臂抓取箱体并搬运至码垛区</li><li>按指定堆叠模式完成码垛（如 2×2 底层 + 交错上层）</li><li>堆叠高度达到 4 层且保持稳定 10 秒以上</li></ol><h2>四、评分标准</h2><p>码垛准确率 40 分、堆叠稳定性 30 分、完成用时 20 分、操作规范性 10 分。倒塌或掉落箱体每次扣 5 分。</p>', '__ROOT__/static/index/images/events/event-05.jpg', '', '2025-02-20 11:00:00', NOW(), NOW()),
(1, 5, 0, 'college,vocational', '高铁游中国赛规则', '结合轨道运行与站点任务，锻炼机器人循迹与精准控制技术。', '<h2>一、竞赛简介</h2><p>高铁游中国赛模拟高铁运行场景，机器人在模拟轨道上进行循迹行驶，沿途经过多个"城市站点"完成指定任务，最终抵达终点站。</p><h2>二、轨道系统</h2><p>轨道总长度约 8 米，采用黑色PVC轨道铺设于白色底板上。轨道包含直道、弯道、岔道、坡道等多种路况。沿线设有 5 个站点标识区。</p><h2>三、站点任务</h2><ul><li><strong>北京站</strong>：人脸识别签到，确认乘客身份</li><li><strong>上海站</strong>：行李安检扫描，识别违禁物品</li><li><strong>广州站</strong>：语音播报站点信息</li><li><strong>成都站</strong>：紧急制动测试</li><li><strong>西安站</strong>：文物展示（机械臂摆放指定角度）</li></ul><h2>四、计分规则</h2><p>基础行驶分 30 分、站点任务分 50 分（每站 10 分）、用时奖励分 20 分。脱轨每次扣 5 分，人工干预每次扣 10 分。</p>', '__ROOT__/static/index/images/events/event-06.jpg', '', '2025-02-15 10:30:00', NOW(), NOW()),
(1, 4, 0, 'middle', '机器人游中国赛规则', '入门级机器人编程与任务挑战，激发青少年科技创新兴趣。', '<h2>一、竞赛目标</h2><p>机器人游中国赛面向中学组参赛选手，是一项入门级机器人竞赛。参赛机器人需在全国地图模型上按指定路线"游览"中国各省份，完成简单的任务挑战。</p><h2>二、竞赛地图</h2><p>地图尺寸 120cm × 80cm，以中国地图轮廓为底图。地图上标注有 34 个省级行政区的位置点，其中 10 个为重点任务省份。</p><h2>三、任务说明</h2><ol><li>机器人从"北京"出发，按抽签决定的路线访问 5 个指定省份</li><li>到达每个省份后，完成该省份对应的特色任务（如播放当地方言、展示地标建筑模型等）</li><li>最终抵达"目的地"省份并完成任务</li></ol><h2>四、适合人群</h2><p>本赛项面向初中及中职在校学生，鼓励使用图形化编程工具（如 Scratch、Mixly）或基础代码编程。重点考察编程逻辑思维与创意表达能力。</p>', '__ROOT__/static/index/images/events/event-07.jpg', '', '2025-02-10 09:00:00', NOW(), NOW()),
(1, 3, 0, 'middle', '遥控灭火赛规则', '遥控操作与灭火任务结合，培养基础工程思维与团队协作能力。', '<h2>一、竞赛目标</h2><p>遥控灭火赛是中学组的经典赛项，要求选手通过遥控操作机器人进入模拟火场，完成火源搜寻与灭火任务，重点考察遥控操作技巧与团队配合。</p><h2>二、竞赛场地</h2><p>场地为 200cm × 200cm 的模拟房间布局，包含墙壁、家具障碍和 3-5 个模拟火源（红色LED灯）。场地内有烟雾模拟（白色薄雾）增加真实感。</p><h2>三、竞赛规则</h2><ul><li>每队 2-3 名选手，1 人操作机器人，其余队员负责观察和指挥</li><li>比赛时间 3 分钟</li><li>机器人需携带灭火装置（水枪或灭火球发射器）</li><li>扑灭一个火源得 20 分，发现隐藏火源额外得 10 分</li></ul><h2>四、器材要求</h2><p>遥控机器人尺寸不超过 25cm × 25cm × 25cm，重量不超过 2kg。遥控方式不限（2.4G/蓝牙/红外均可）。灭火装置储水量不超过 200ml。</p>', '__ROOT__/static/index/images/events/event-08.jpg', '', '2025-01-20 14:00:00', NOW(), NOW());
INSERT INTO `competition_notices` (`status`, `sort`, `is_deleted`, `category_key`, `title`, `summary`, `content`, `cover_image`, `source_url`, `published_at`, `create_at`, `update_at`) VALUES
(1, 100, 0, 'important', '关于举办第十五届中国教育机器人大赛的通知', '经中国人工智能学会批准，第十五届中国教育机器人大赛将于 2025 年 10 月在广东东莞举办。', '<h2>各参赛院校、有关单位：</h2><p>经中国人工智能学会批准，第十五届中国教育机器人大赛（ERCC 2025）定于 <strong>2025 年 10 月 18 日至 20 日</strong>在广东省东莞市举办。本届大赛由清华大学、东南大学、南京大学等高校联合发起，中国人工智能学会主办。</p><h2>一、竞赛时间与地点</h2><ul><li>时间：2025 年 10 月 18 日 — 20 日（10 月 17 日报到）</li><li>地点：东莞松山湖国际创新创业社区</li><li>报名截止时间：2025 年 9 月 15 日</li></ul><h2>二、竞赛项目</h2><p>本届大赛设机器人擂台赛、智能搬运、智能消防、智能服务机器人、搬运码垛、高铁游中国、机器人游中国、遥控灭火等 8 个赛项，分大学本科组、高职高专组、中学中职组三个组别。</p><h2>三、报名方式</h2><p>请各参赛队伍登录大赛官方网站（www.ercc.org.cn）完成在线报名，并按要求提交报名材料。报名费标准为：大学组 500 元/队，中学组 300 元/队。</p><h2>四、联系方式</h2><p>组委会秘书处：广东省东莞市松山湖高新区大学路 1 号</p><p>联系电话：0769-XXXX-XXXX</p><p>电子邮箱：ercc2025@ercc.org.cn</p>', '', '', '2025-04-01 09:00:00', NOW(), NOW()),
(1, 95, 0, 'schedule', 'ERCC 2025 赛程安排调整公告', '因场地协调原因，部分赛项的比赛时间有所调整，请各参赛队伍留意最新赛程。', '<h2>关于赛程调整的通知</h2><p>尊敬的各位参赛队伍：</p><p>因东莞松山湖国际创新创业社区场地协调安排，经大赛组委会研究决定，对部分赛项的比赛时间进行调整。具体调整如下：</p><table><tr><th>赛项</th><th>原安排</th><th>调整后</th></tr><tr><td>机器人擂台赛</td><td>10月18日上午</td><td>10月18日下午</td></tr><tr><td>智能搬运</td><td>10月18日下午</td><td>10月19日上午</td></tr><tr><td>智能消防</td><td>10月19日上午</td><td>10月19日下午</td></tr><tr><td>搬运码垛</td><td>10月19日下午</td><td>10月20日上午</td></tr></table><p>其余赛项时间不变。请各参赛队伍根据最新赛程合理安排出行与备赛计划。如有疑问，请联系组委会秘书处。</p>', '', '', '2025-03-28 10:00:00', NOW(), NOW()),
(1, 90, 0, 'media', '东莞日报 | 自由对抗、智能消防竞赛......这场机器人比赛上演十八般武艺', '全国百余所高校选手齐聚东莞，在机器人擂台赛、智能搬运、智能消防等多个赛项中展开激烈角逐。', '<p>【东莞日报 2020-12-09】12 月 8 日，第十四届中国教育机器人大赛总决赛在东莞松山湖圆满落幕。来自全国 200 余所院校的 3000 余名参赛选手齐聚一堂，在机器人擂台赛、智能搬运、智能消防、智能服务机器人等 8 个赛项中展开激烈角逐。</p><p>大赛现场，机器人擂台赛区战况最为激烈。清华大学代表队设计的"铁甲雄狮"凭借出色的结构设计和高扭矩驱动电机，在决赛中以 3:1 的比分战胜东南大学"闪电侠"，夺得本科组冠军。</p><p>在智能搬运赛区，参赛机器人需要在模拟物流仓库中完成货物的识别、抓取与搬运。高职组的选手们展示了令人印象深刻的机械臂控制精度，部分队伍实现了亚毫米级的抓取定位。</p><p>大赛组委会主席、清华大学教授张明表示："中国教育机器人大赛已连续举办十四届，累计培养创新型工程师超过 10 万人。大赛不仅是竞技平台，更是推动产教融合、促进机器人教育发展的重要力量。"</p><p>本届大赛首次引入 AI 智能评分辅助系统，通过计算机视觉技术实时监测比赛过程，提升了评分的客观性与效率。该系统由南京大学团队研发，后续将在全国推广应用。</p>', '__ROOT__/static/index/images/news-feature.png', 'https://www.ercc.org.cn/news/news1/2020-12-09/188.html', '2020-12-09 08:00:00', NOW(), NOW()),
(1, 85, 0, 'media', '松山湖融媒体中心 | 科技达人齐聚松山湖畔 创新竞技绽放青春风采', '来自全国各地的高校学子在松山湖展开机器人技术大比拼，展现新时代青年的科技创新力量。', '<p>【松山湖融媒体中心】12 月 8 日至 9 日，第十四届中国教育机器人大赛在东莞松山湖国际创新创业社区举办。本次大赛吸引来自清华大学、东南大学、南京大学、哈尔滨工业大学等全国 200 余所高校的 3000 余名选手参赛。</p><p>走进比赛现场，各种造型的机器人让人目不暇接。有的机器人形似装甲战车，配备高速旋转的滚筒；有的机器人小巧灵活，采用全向轮设计；还有的机器人搭载了多关节机械臂，动作精准流畅。</p><p>在智能服务机器人赛区，评委们模拟了酒店大堂的真实场景。参赛机器人需要识别"客人"的语音指令，引导至指定房间，并完成递送物品等任务。来自深圳职业技术学院的"小松"机器人表现尤为出色，其多轮对话理解和动态避障能力获得评委一致好评。</p><p>松山湖管委会相关负责人表示，本次大赛是松山湖建设"科技新城"的重要组成部分，未来将继续引进高水平科技赛事，打造粤港澳大湾区青年创新创业高地。</p>', '__ROOT__/static/index/images/showcase-card-1.png', 'https://www.ercc.org.cn/news/news1/2020-12-09/187.html', '2020-12-09 10:00:00', NOW(), NOW()),
(1, 80, 0, 'award', '第十四届中国教育机器人大赛获奖名单公示', '现将第十四届大赛各赛项获奖名单予以公示，公示期为 7 个工作日。', '<h2>获奖名单公示</h2><p>第十四届中国教育机器人大赛已圆满结束。经评审委员会评审，现将各赛项获奖名单予以公示（详见附件）。公示期为 2020 年 12 月 10 日至 12 月 16 日，共 7 个工作日。</p><h2>本科组特等奖（部分）</h2><table><tr><th>赛项</th><th>学校</th><th>队伍名称</th></tr><tr><td>机器人擂台赛</td><td>清华大学</td><td>铁甲雄狮</td></tr><tr><td>智能搬运</td><td>东南大学</td><td>搬运大师</td></tr><tr><td>智能消防</td><td>南京大学</td><td>烈焰克星</td></tr><tr><td>智能服务机器人</td><td>哈尔滨工业大学</td><td>服务之星</td></tr></table><h2>高职组特等奖（部分）</h2><table><tr><th>赛项</th><th>学校</th><th>队伍名称</th></tr><tr><td>搬运码垛</td><td>深圳职业技术学院</td><td>码垛专家</td></tr><tr><td>高铁游中国</td><td>东莞职业技术学院</td><td>高铁先锋</td></tr></table><h2>中学组特等奖（部分）</h2><table><tr><th>赛项</th><th>学校</th><th>队伍名称</th></tr><tr><td>机器人游中国</td><td>北京四中</td><td>游遍中华</td></tr><tr><td>遥控灭火</td><td>华南师大附中</td><td>烈火英雄</td></tr></table><p>如对公示结果有异议，请在公示期内以书面形式向组委会提出。邮箱：ercc@ercc.org.cn</p>', '', '', '2020-12-10 09:00:00', NOW(), NOW()),
(1, 75, 0, 'important', 'ERCC 2025 竞赛套件采购指南', '为确保公平竞争，本届大赛所有参赛套件须为组委会认证产品，请按指南采购。', '<h2>关于竞赛套件采购的通知</h2><p>各参赛院校：</p><p>为确保竞赛的公平性与器材一致性，第十五届中国教育机器人大赛所有参赛队伍须使用组委会认证的教育机器人竞赛套件。未经认证的器材不得参赛。</p><h2>认证套件清单</h2><table><tr><th>赛项</th><th>套件型号</th><th>适用组别</th></tr><tr><td>机器人擂台赛</td><td>ERCC-RB-2025</td><td>本科/中学</td></tr><tr><td>智能搬运</td><td>ERCC-TR-2025</td><td>全组别</td></tr><tr><td>智能消防</td><td>ERCC-FR-2025</td><td>本科/高职</td></tr><tr><td>智能服务机器人</td><td>ERCC-SR-2025</td><td>本科/高职</td></tr><tr><td>搬运码垛</td><td>ERCC-PM-2025</td><td>高职</td></tr><tr><td>高铁游中国</td><td>ERCC-HT-2025</td><td>本科/高职</td></tr><tr><td>机器人游中国</td><td>ERCC-RC-2025</td><td>中学</td></tr><tr><td>遥控灭火</td><td>ERCC-FF-2025</td><td>中学</td></tr></table><h2>采购方式</h2><p>1. 线上商城：访问 www.ercc.org.cn/store 在线选购</p><p>2. 电话订购：拨打 400-XXX-XXXX 联系客服人员</p><p>3. 批量采购：10 套以上享受团体优惠，请联系组委会商务组</p><p>采购截止日期：2025 年 8 月 31 日</p>', '', '', '2025-03-15 11:00:00', NOW(), NOW()),
(1, 70, 0, 'schedule', '第十五届大赛报名系统开放通知', 'ERCC 2025 在线报名系统已正式开放，请各参赛队伍在规定时间内完成报名。', '<h2>报名系统开放通知</h2><p>尊敬的各位指导老师、参赛选手：</p><p>第十五届中国教育机器人大赛在线报名系统已于 <strong>2025 年 3 月 1 日 0:00</strong> 正式开放。请各参赛队伍登录大赛官网完成报名注册。</p><h2>报名流程</h2><ol><li>访问 www.ercc.org.cn，点击"在线报名"入口</li><li>注册账号（已注册用户可直接登录）</li><li>填写参赛队伍信息（队伍名称、指导老师、队员名单）</li><li>选择参赛赛项与组别</li><li>上传报名材料（学生证扫描件、报名表盖章件）</li><li>在线缴纳报名费</li><li>等待组委会审核（3-5 个工作日）</li></ol><h2>重要时间节点</h2><table><tr><th>事项</th><th>截止时间</th></tr><tr><td>报名开始</td><td>2025年3月1日</td></tr><tr><td>早鸟优惠截止</td><td>2025年6月30日</td></tr><tr><td>报名截止</td><td>2025年9月15日</td></tr><tr><td>材料补交截止</td><td>2025年9月20日</td></tr></table>', '', '', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 65, 0, 'media', '中新网广东 | 全国百余所高校选手上演机器人大赛', '第九届中国教育机器人大赛总决赛在佛山圆满落幕，吸引全国百余所高校参加。', '<p>【中新网广东 2019-10-25】第九届中国教育机器人大赛总决赛于 10 月 24 日至 25 日在佛山潭洲国际会展中心举行。本次大赛汇聚全国 100 余所高校、超过 1000 名学生参赛，创下历届参赛规模新高。</p><p>大赛现场，各种形态的机器人在擂台上激烈对抗、在赛道上精准行驶、在模拟场景中灵活操作。裁判长介绍，本届大赛的参赛机器人技术水平较往届有显著提升，特别是在自主导航和视觉识别方面进步明显。</p><p>中国教育机器人大赛自 2011 年创办以来，已成功举办九届。大赛由中国人工智能学会主办，清华大学、东南大学等高校联合发起，旨在推动中国机器人教育普及与产教融合发展。</p><p>本届大赛还设立了"最佳创新奖""最佳设计奖""最佳人气奖"等特别奖项，鼓励参赛队伍在技术创新和外观设计方面展现创意。</p>', '__ROOT__/static/index/images/showcase-feature.jpg', 'https://www.ercc.org.cn/news/news1/2019-10-25/134.html', '2019-10-25 09:00:00', NOW(), NOW());
INSERT INTO `competition_kits` (`status`, `sort`, `is_deleted`, `category_keys`, `title`, `summary`, `content`, `cover_image`, `source_url`, `published_at`, `create_at`, `update_at`) VALUES
(1, 10, 0, 'college,middle', '机器人擂台赛标准套件 ERCC-RB-2025', '专为机器人擂台赛设计的标准竞赛套件，包含底盘、驱动电机、控制板及基础结构件。', '<h2>产品概述</h2><p>ERCC-RB-2025 是第十五届中国教育机器人大赛机器人擂台赛赛项的官方认证标准套件。套件采用模块化设计，支持快速拆装和结构扩展，适合本科组与中学组参赛使用。</p><h2>套件配置清单</h2><table><tr><th>组件</th><th>规格</th><th>数量</th></tr><tr><td>铝合金底盘</td><td>200×200mm，2mm厚</td><td>1</td></tr><tr><td>直流减速电机</td><td>12V，200RPM，配编码器</td><td>2</td></tr><tr><td>电机驱动板</td><td>双路H桥，支持PWM调速</td><td>1</td></tr><tr><td>主控板</td><td>STM32F103，兼容Arduino</td><td>1</td></tr><tr><td>锂电池组</td><td>12V 3000mAh，带保护板</td><td>1</td></tr><tr><td>结构件包</td><td>铝合金型材、连接件</td><td>1套</td></tr><tr><td>工具包</td><td>螺丝刀、扳手、扎带等</td><td>1套</td></tr></table><h2>技术参数</h2><ul><li>整机重量：约 1.8kg（含电池）</li><li>最大行驶速度：1.2m/s</li><li>续航时间：约 45 分钟</li><li>通信方式：蓝牙 5.0 / 2.4G 遥控</li></ul><h2>适用赛项</h2><p>机器人擂台赛（大学本科组、中学中职组）</p>', '__ROOT__/static/index/images/events/event-01.jpg', 'https://www.ercc.org.cn/store/rb-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 9, 0, 'college,vocational,middle', '智能搬运套件 ERCC-TR-2025', '集成传感器与机械臂模块的搬运竞赛套件，锻炼路径规划与物流自动化思维。', '<h2>产品概述</h2><p>ERCC-TR-2025 智能搬运套件是大赛智能搬运赛项的官方认证套件。套件集成了机器视觉、机械臂控制、循迹导航等核心功能模块，帮助参赛队伍快速搭建具备完整搬运能力的竞赛机器人。</p><h2>核心组件</h2><table><tr><th>组件</th><th>说明</th></tr><tr><td>OpenMV 视觉模块</td><td>支持颜色识别、形状检测、二维码扫描</td></tr><tr><td>3DOF 机械臂</td><td>铝合金结构，舵机驱动，最大负载 500g</td></tr><tr><td>全向移动底盘</td><td>麦克纳姆轮设计，支持横移与原地旋转</td></tr><tr><td>激光测距传感器</td><td>量程 0.1-12m，精度 ±2mm</td></tr><tr><td>主控系统</td><td>树莓派 4B + 扩展板，预装 OpenCV</td></tr></table><h2>软件支持</h2><p>套件提供完整的示例代码库，包括：</p><ul><li>循迹行驶基础程序</li><li>颜色识别与分拣示例</li><li>机械臂抓取控制程序</li><li>路径规划算法模板</li></ul><h2>适用组别</h2><p>大学本科组、高职高专组、中学中职组（全组别通用）</p>', '__ROOT__/static/index/images/events/event-02.jpg', 'https://www.ercc.org.cn/store/tr-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 8, 0, 'college,vocational', '智能消防竞赛套件 ERCC-FR-2025', '模拟真实消防场景的专业竞赛套件，培养机器人在复杂环境中的感知与决策能力。', '<h2>产品概述</h2><p>ERCC-FR-2025 是专为智能消防赛项开发的高阶竞赛套件。套件配备多传感器融合系统，支持自主导航、火焰探测、灭火操作等完整任务链。</p><h2>传感器系统</h2><ul><li><strong>红外火焰传感器阵列</strong>：8 路红外探测，探测角度 120°，探测距离 0-3m</li><li><strong>烟雾传感器</strong>：MQ-2 烟雾检测模块</li><li><strong>温湿度传感器</strong>：DHT22，精度 ±0.5°C</li><li><strong>超声波避障</strong>：HC-SR04 × 3，前方及两侧实时测距</li><li><strong>9轴姿态传感器</strong>：MPU9250，支持姿态解算</li></ul><h2>灭火系统</h2><p>套件配备微型水泵灭火装置，储水量 150ml，喷射距离 1.5m。也可选配 CO₂ 灭火装置（需另购气瓶）。</p><h2>适用赛项</h2><p>智能消防赛（大学本科组、高职高专组）</p>', '__ROOT__/static/index/images/events/event-03.jpg', 'https://www.ercc.org.cn/store/fr-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 7, 0, 'college,vocational', '智能服务机器人套件 ERCC-SR-2025', '面向服务场景的人机交互竞赛套件，提升多传感器融合应用能力。', '<h2>产品概述</h2><p>ERCC-SR-2025 是一款面向服务机器人赛项的高集成度竞赛套件。套件以人形服务机器人为基础平台，集成了语音交互、视觉识别、自主导航、机械操作等全栈功能。</p><h2>硬件配置</h2><table><tr><th>模块</th><th>规格</th></tr><tr><td>底盘</td><td>差速驱动，直径 35cm，最大速度 1m/s</td></tr><tr><td>升降躯干</td><td>电动升降，高度调节范围 80-120cm</td></tr><tr><td>头部</td><td>双自由度云台，集成 720P 摄像头</td></tr><tr><td>手臂</td><td>5DOF 机械臂 × 2，最大伸展 45cm</td></tr><tr><td>语音系统</td><td>4 麦克风阵列 + 双扬声器，支持离线语音识别</td></tr><tr><td>显示屏</td><td>7 寸触摸屏，用于信息展示与交互</td></tr></table><h2>软件平台</h2><p>预装 Ubuntu 20.04 + ROS Noetic，提供完整的 SLAM 导航、语音对话、物体识别等 ROS 功能包。支持 Python/C++ 二次开发。</p>', '__ROOT__/static/index/images/events/event-04.jpg', 'https://www.ercc.org.cn/store/sr-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 6, 0, 'vocational', '搬运码垛专业套件 ERCC-PM-2025', '工业级码垛与搬运任务训练平台，对接智能制造产业需求。', '<h2>产品概述</h2><p>ERCC-PM-2025 是专为高职组搬运码垛赛项设计的工业级竞赛套件。套件以 SCARA 机械臂为核心，配合传送带模块和托盘定位系统，完整还原工业码垛场景。</p><h2>核心组件</h2><table><tr><th>组件</th><th>规格</th></tr><tr><td>SCARA 机械臂</td><td>4轴，臂展 400mm，重复定位精度 ±0.05mm</td></tr><tr><td>真空吸盘末端</td><td>Φ20mm 硅胶吸盘，真空度 -0.08MPa</td></tr><tr><td>传送带模块</td><td>调速传送带，带宽 15cm，长 100cm</td></tr><tr><td>托盘定位台</td><td>60×40cm 标准托盘 + 光电定位传感器</td></tr><tr><td>PLC 控制器</td><td>西门子 S7-1200，支持梯形图编程</td></tr></table><h2>特色功能</h2><ul><li>支持码垛模式编程：层叠式、交错式、旋转式</li><li>配备工业级 HMI 触摸屏，实时监控运行状态</li><li>提供西门子 TIA Portal 示例工程</li></ul><h2>适用赛项</h2><p>搬运码垛赛（高职高专组）</p>', '__ROOT__/static/index/images/events/event-05.jpg', 'https://www.ercc.org.cn/store/pm-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 5, 0, 'college,vocational', '高铁游中国套件 ERCC-HT-2025', '结合轨道运行与站点任务，锻炼机器人循迹与精准控制技术。', '<h2>产品概述</h2><p>ERCC-HT-2025 高铁游中国赛项专用套件，以磁循迹/色带循迹机器人为基础平台，配备多站点任务执行模块，完整支持高铁游中国赛项全部任务需求。</p><h2>套件内容</h2><table><tr><th>组件</th><th>说明</th></tr><tr><td>循迹小车底盘</td><td>双轮差速驱动，配磁传感器/灰度传感器阵列</td></tr><tr><td>RFID 读写模块</td><td>支持 13.56MHz 标签识别，用于站点签到</td></tr><tr><td>语音播报模块</td><td>MP3 播放模块，预存 30 条站点播报音频</td></tr><tr><td>伺服云台</td><td>双轴云台，用于"文物展示"任务</td></tr><tr><td>红外避障模块</td><td>前方 3 路红外测距，支持紧急制动</td></tr><tr><td>轨道配件包</td><td>PVC 轨道条 8m、弯道配件、站点标识牌</td></tr></table><h2>任务支持</h2><p>完整支持北京站签到、上海站安检、广州站播报、成都站制动、西安站展示等全部 5 个站点任务。</p>', '__ROOT__/static/index/images/events/event-06.jpg', 'https://www.ercc.org.cn/store/ht-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 4, 0, 'middle', '机器人游中国入门套件 ERCC-RC-2025', '入门级机器人编程与任务挑战套件，激发青少年科技创新兴趣。', '<h2>产品概述</h2><p>ERCC-RC-2025 是面向中学组的入门级竞赛套件。套件以图形化编程为核心，配合简单易用的机器人平台，帮助中学生快速上手机器人编程与竞赛。</p><h2>编程方式</h2><ul><li><strong>Mixly 图形化编程</strong>：拖拽式积木编程，无需代码基础</li><li><strong>Python 代码编程</strong>：支持 MicroPython，适合有一定基础的学生</li><li><strong>手机 APP 遥控</strong>：蓝牙连接，支持手动遥控模式</li></ul><h2>硬件配置</h2><table><tr><th>组件</th><th>规格</th></tr><tr><td>主控板</td><td>ESP32，双核 240MHz，内置 WiFi/蓝牙</td></tr><tr><td>电机</td><td>TT 减速电机 × 2，配橡胶轮胎</td></tr><tr><td>传感器</td><td>循迹传感器 × 2、超声波 × 1、颜色传感器 × 1</td></tr><tr><td>LED 显示</td><td>8×8 LED 点阵屏，用于展示省份图标</td></tr><tr><td>喇叭</td><td>迷你喇叭，用于方言播报任务</td></tr></table><h2>教学资源</h2><p>随套件附赠《机器人游中国备赛指南》一本，包含 10 个课时的编程教程、示例程序和任务解决方案。</p>', '__ROOT__/static/index/images/events/event-07.jpg', 'https://www.ercc.org.cn/store/rc-2025', '2025-03-01 00:00:00', NOW(), NOW()),
(1, 3, 0, 'middle', '遥控灭火套件 ERCC-FF-2025', '遥控操作与灭火任务结合，培养基础工程思维与团队协作能力。', '<h2>产品概述</h2><p>ERCC-FF-2025 遥控灭火赛项专用套件，包含遥控小车底盘、灭火装置和完整遥控系统。套件设计注重操控手感和可靠性，适合中学生快速上手。</p><h2>遥控系统</h2><ul><li><strong>2.4G 遥控器</strong>：6 通道，操控距离 100m+，带 LCD 显示屏</li><li><strong>接收机</strong>：集成于小车底盘，支持失控保护</li><li><strong>操控模式</strong>：支持单手/双手两种握持方式</li></ul><h2>灭火装置</h2><table><tr><th>类型</th><th>规格</th></tr><tr><td>水枪式</td><td>微型水泵 + 软管，射程 2m，储水 200ml</td></tr><tr><td>灭火球式（选配）</td><td>发射器 × 1，配套灭火球 10 颗</td></tr></table><h2>底盘参数</h2><p>四轮驱动，金属齿轮减速电机，最大速度 1.5m/s。配备前保险杠和顶部防护架，碰撞后可快速复位。整机重量 1.2kg（不含灭火装置）。</p>', '__ROOT__/static/index/images/events/event-08.jpg', 'https://www.ercc.org.cn/store/ff-2025', '2025-03-01 00:00:00', NOW(), NOW());
INSERT INTO `competition_materials` (`status`, `sort`, `is_deleted`, `category_key`, `title`, `summary`, `content`, `file_url`, `file_size`, `published_at`, `create_at`, `update_at`) VALUES
(1, 100, 0, 'rules', '2025 第十五届中国教育机器人大赛竞赛规则总册', '包含全部 8 个赛项的竞赛规则、评分标准、场地规格与器材要求。', '<h2>文件说明</h2><p>本文件为第十五届中国教育机器人大赛官方竞赛规则总册，涵盖大赛全部 8 个赛项的详细规则说明。</p><h2>目录</h2><ol><li>大赛总则</li><li>机器人擂台赛规则</li><li>智能搬运赛规则</li><li>智能消防赛规则</li><li>智能服务机器人规则</li><li>搬运码垛赛规则</li><li>高铁游中国赛规则</li><li>机器人游中国赛规则</li><li>遥控灭火赛规则</li><li>附录：评分表模板、场地图纸</li></ol><h2>适用范围</h2><p>本规则适用于第十五届中国教育机器人大赛全部组别（大学本科组、高职高专组、中学中职组）。各赛项具体规则详见对应章节。</p><h2>版本信息</h2><p>版本：V1.0 | 发布日期：2025-03-15 | 组委会保留最终解释权</p>', 'https://www.ercc.org.cn/download/rules-2025.pdf', 5242880, '2025-03-15 10:00:00', NOW(), NOW()),
(1, 95, 0, 'tech', '智能搬运赛项技术手册 V2.0', '传感器配置指南、示例程序、常见故障排查与优化建议。', '<h2>手册概述</h2><p>本手册为智能搬运赛项参赛队伍提供全面的技术指导，涵盖传感器选型与配置、示例程序解析、常见问题排查等内容。</p><h2>第一章：传感器配置</h2><ul><li>灰度传感器阵列的安装位置与调试方法</li><li>OpenMV 摄像头颜色阈值校准</li><li>激光测距传感器的串口通信配置</li></ul><h2>第二章：示例程序</h2><p>提供完整的 Arduino / STM32 / 树莓派三套示例代码，包括：</p><ol><li>基础循迹程序</li><li>颜色识别与分拣程序</li><li>机械臂坐标抓取程序</li><li>综合任务调度程序</li></ol><h2>第三章：故障排查</h2><table><tr><th>故障现象</th><th>可能原因</th><th>解决方案</th></tr><tr><td>循迹不稳定</td><td>传感器高度不当/环境光干扰</td><td>调整安装高度 8-12mm，避开强光直射</td></tr><tr><td>颜色识别错误</td><td>阈值设置不当</td><td>使用 OpenMV IDE 重新标定 LAB 阈值</td></tr><tr><td>机械臂抓取失败</td><td>坐标偏差/夹持力不足</td><td>重新标定坐标系，调整舵机角度</td></tr></table>', 'https://www.ercc.org.cn/download/tech-manual-v2.pdf', 3145728, '2025-03-10 14:30:00', NOW(), NOW()),
(1, 90, 0, 'forms', '第十五届大赛参赛报名表', '参赛队伍信息登记表，需加盖学校或单位公章后扫描上传。', '<h2>填写说明</h2><p>请如实填写以下信息，报名表需打印后加盖学校（或参赛单位）公章，扫描为 PDF 格式上传至报名系统。</p><h2>队伍信息</h2><ul><li>队伍名称（中英文）</li><li>参赛赛项</li><li>参赛组别（本科/高职/中学）</li><li>所属学校全称</li></ul><h2>成员信息</h2><table><tr><th>角色</th><th>姓名</th><th>身份证号</th><th>学生证号</th><th>联系电话</th></tr><tr><td>指导老师</td><td></td><td></td><td>—</td><td></td></tr><tr><td>队长</td><td></td><td></td><td></td><td></td></tr><tr><td>队员1</td><td></td><td></td><td></td><td></td></tr><tr><td>队员2</td><td></td><td></td><td></td><td></td></tr></table><h2>注意事项</h2><p>1. 每队限 1-3 名队员，1 名指导老师</p><p>2. 队员须为在读学生，指导老师须为在职教师</p><p>3. 同一指导老师最多指导 3 支队伍</p>', 'https://www.ercc.org.cn/download/registration-form-2025.docx', 512000, '2025-03-01 09:00:00', NOW(), NOW()),
(1, 85, 0, 'video', '机器人擂台赛培训视频（全 12 集）', '从基础搭建到攻防策略的完整教学视频系列，适合零基础参赛队伍。', '<h2>视频系列介绍</h2><p>本系列视频由历届大赛冠军队伍指导教师联合录制，系统讲解机器人擂台赛的备赛要点，从机械结构设计到控制算法优化，覆盖备赛全周期。</p><h2>课程大纲</h2><table><tr><th>集数</th><th>主题</th><th>时长</th></tr><tr><td>第1集</td><td>赛项介绍与规则解读</td><td>25分钟</td></tr><tr><td>第2集</td><td>底盘结构设计要点</td><td>35分钟</td></tr><tr><td>第3集</td><td>驱动系统选型与调试</td><td>30分钟</td></tr><tr><td>第4集</td><td>传感器布局策略</td><td>28分钟</td></tr><tr><td>第5集</td><td>进攻策略设计</td><td>32分钟</td></tr><tr><td>第6集</td><td>防守与反击技巧</td><td>30分钟</td></tr><tr><td>第7集</td><td>控制算法优化</td><td>40分钟</td></tr><tr><td>第8集</td><td>实战演练与调试</td><td>45分钟</td></tr><tr><td>第9集</td><td>历届优秀案例分析</td><td>35分钟</td></tr><tr><td>第10集</td><td>赛前准备与检查清单</td><td>20分钟</td></tr><tr><td>第11集</td><td>现场应对策略</td><td>25分钟</td></tr><tr><td>第12集</td><td>赛后总结与技术沉淀</td><td>20分钟</td></tr></table><p>总时长：约 6.5 小时 | 格式：MP4 1080P | 配套资料：示例代码、设计图纸</p>', 'https://www.ercc.org.cn/download/training-video-rb-2025.mp4', 2147483648, '2025-02-28 16:00:00', NOW(), NOW()),
(1, 80, 0, 'tech', '智能消防赛项场地搭建指南', '场地尺寸、道具摆放与判罚细则图解说明，含 3D 模型文件。', '<h2>指南说明</h2><p>本指南提供智能消防赛项场地的完整搭建方案，包含尺寸标注、材料清单、道具摆放规则和 3D 模型文件（SketchUp 格式）。</p><h2>场地总览</h2><ul><li>总面积：300cm × 300cm</li><li>房间数量：4 个（客厅、卧室 A、卧室 B、走廊）</li><li>墙壁高度：15cm（白色 PVC 板）</li><li>地面材质：白色哑光 PVC 地板</li></ul><h2>道具清单</h2><table><tr><th>道具</th><th>数量</th><th>尺寸</th><th>材质</th></tr><tr><td>沙发模型</td><td>1</td><td>30×15×12cm</td><td>EVA 泡沫</td></tr><tr><td>茶几模型</td><td>1</td><td>20×20×8cm</td><td>EVA 泡沫</td></tr><tr><td>床铺模型</td><td>2</td><td>25×20×10cm</td><td>EVA 泡沫</td></tr><tr><td>模拟火源</td><td>5</td><td>直径 5cm</td><td>红色 LED + 亚克力罩</td></tr><tr><td>干扰光源</td><td>3</td><td>直径 5cm</td><td>橙色/黄色 LED</td></tr></table><h2>3D 模型文件</h2><p>附件包含完整的 SketchUp 模型文件（.skp）和 STL 打印文件，可自行 3D 打印小型道具。</p>', 'https://www.ercc.org.cn/download/field-guide-fire-2025.pdf', 2097152, '2025-02-20 11:00:00', NOW(), NOW()),
(1, 75, 0, 'forms', '指导老师信息登记表', '用于登记指导教师联系方式、职称信息及研究领域。', '<h2>填写说明</h2><p>请每位指导老师单独填写一份登记表，用于组委会建立教师通讯录和发送大赛相关资料。</p><h2>教师信息</h2><ul><li>姓名、性别、出生年月</li><li>所属学校及院系</li><li>职称（教授/副教授/讲师/其他）</li><li>研究领域</li><li>联系电话、电子邮箱</li><li>通讯地址及邮编</li></ul><h2>指导经历</h2><p>请简要填写近五年指导学生参加科技竞赛的经历（赛项名称、获奖等级、年份）。</p><h2>隐私声明</h2><p>组委会承诺对教师个人信息严格保密，仅用于大赛组织工作，不会向第三方透露。</p>', 'https://www.ercc.org.cn/download/teacher-form-2025.docx', 256000, '2025-02-15 10:30:00', NOW(), NOW());
INSERT INTO `past_competitions` (`status`, `sort`, `is_deleted`, `year`, `title`, `summary`, `content`, `cover_image`, `source_url`, `published_at`, `create_at`, `update_at`) VALUES
(1, 10, 0, 2024, '第十四届中国教育机器人大赛', '广东东莞 | 汇聚全国 200 余所院校、超 3000 名选手，首次引入 AI 智能评分辅助系统。', '<h2>大赛概况</h2><p>第十四届中国教育机器人大赛于 2024 年 10 月 18 日至 20 日在广东省东莞市松山湖国际创新创业社区成功举办。本次大赛汇聚全国 200 余所院校的 3000 余名选手，参赛规模创历史新高。</p><h2>赛项设置</h2><p>本届大赛共设 8 个赛项：机器人擂台赛、智能搬运、智能消防、智能服务机器人、搬运码垛、高铁游中国、机器人游中国、遥控灭火。分大学本科组、高职高专组、中学中职组三个组别。</p><h2>技术创新</h2><p>本届大赛首次引入 AI 智能评分辅助系统，由南京大学人工智能学院研发。该系统基于计算机视觉技术，可实时识别比赛过程中的关键事件（如机器人出界、任务完成等），显著提升了评分的客观性和效率。</p><h2>获奖统计</h2><table><tr><th>奖项</th><th>数量</th></tr><tr><td>特等奖</td><td>24 项</td></tr><tr><td>一等奖</td><td>72 项</td></tr><tr><td>二等奖</td><td>144 项</td></tr><tr><td>三等奖</td><td>216 项</td></tr></table><h2>精彩瞬间</h2><p>大赛期间，东莞日报、松山湖融媒体中心等主流媒体进行了全程跟踪报道。大赛开幕式直播观看人次突破 100 万，相关话题在社交媒体上获得广泛关注。</p>', '__ROOT__/static/index/images/events/event-01.jpg', 'https://www.ercc.org.cn/news5/', '2024-10-20 18:00:00', NOW(), NOW()),
(1, 9, 0, 2023, '第十三届中国教育机器人大赛', '广东佛山 | 以"智造未来"为主题，新增智能服务机器人赛项，吸引百余所高校参与。', '<h2>大赛概况</h2><p>第十三届中国教育机器人大赛于 2023 年 10 月 20 日至 22 日在广东省佛山市举办。本届大赛以"智造未来"为主题，新增智能服务机器人赛项，进一步丰富了竞赛内容。</p><h2>新增赛项</h2><p>智能服务机器人赛项模拟酒店/医院服务场景，要求参赛机器人完成迎宾引导、物品递送、语音交互等多项任务。该赛项一经推出便受到热烈欢迎，共有 86 支队伍报名参赛。</p><h2>产教融合</h2><p>本届大赛与佛山当地智能制造企业深度合作，设立了"企业命题"专项赛。美的集团、碧桂园机器人等企业提供真实工业场景题目，获奖方案有机会直接转化应用。</p><h2>国际交流</h2><p>大赛首次邀请海外队伍参赛，新加坡国立大学、马来西亚理工大学等院校派出代表队参加表演赛，促进了国际间的机器人教育交流。</p>', '__ROOT__/static/index/images/events/event-02.jpg', 'https://www.ercc.org.cn/news5/', '2023-10-22 18:00:00', NOW(), NOW()),
(1, 8, 0, 2022, '第十二届中国教育机器人大赛', '线上 + 线下混合 | 因应特殊时期的创新办赛模式，线上直播观看人次突破 500 万。', '<h2>大赛概况</h2><p>第十二届中国教育机器人大赛于 2022 年 10 月采用线上 + 线下混合模式举办。线下赛场设在广东东莞，同时通过线上直播平台向全国观众开放。</p><h2>创新办赛</h2><p>为适应疫情防控要求，本届大赛创新性地采用混合办赛模式：现场参赛队伍在东莞完成实体机器人比赛，部分无法到场的队伍通过线上提交仿真视频参赛。评审委员会对两种形式的作品统一评审标准。</p><h2>线上直播</h2><p>大赛通过 B 站、抖音、视频号等多平台同步直播，累计观看人次突破 500 万，创历史新高。直播期间，弹幕互动热烈，"机器人格斗"话题一度登上热搜榜。</p><h2>仿真赛项</h2><p>本届大赛首次设立纯线上仿真赛项，参赛队伍使用 Webots 仿真平台完成机器人编程与测试。该赛项降低了参赛门槛，让更多偏远地区学校有机会参与大赛。</p>', '__ROOT__/static/index/images/events/event-03.jpg', 'https://www.ercc.org.cn/news5/', '2022-10-23 18:00:00', NOW(), NOW()),
(1, 7, 0, 2021, '第十一届中国教育机器人大赛', '广东深圳 | 大赛被列入全国普通高校大学生竞赛指数清单，获多所高校保研加分认可。', '<h2>大赛概况</h2><p>第十一届中国教育机器人大赛于 2021 年 10 月 15 日至 17 日在广东省深圳市举办。本届大赛具有重要的里程碑意义——大赛正式被列入全国普通高校大学生竞赛指数清单。</p><h2>里程碑意义</h2><p>被列入竞赛指数清单意味着 ERCC 的获奖成绩可获得多所高校的保研加分认可。据统计，2022 年共有 37 所高校在保研政策中明确将 ERCC 获奖列入加分项。</p><h2>深圳特色</h2><p>本届大赛充分利用深圳科技创新之都的资源优势，邀请了大疆创新、优必选、固高科技等本地企业的技术专家担任评委，并设置了企业参观交流环节。</p><h2>参赛数据</h2><table><tr><th>指标</th><th>数据</th></tr><tr><td>参赛院校</td><td>186 所</td></tr><tr><td>参赛队伍</td><td>612 支</td></tr><tr><td>参赛选手</td><td>1836 人</td></tr><tr><td>覆盖省份</td><td>28 个</td></tr></table>', '__ROOT__/static/index/images/events/event-04.jpg', 'https://www.ercc.org.cn/news5/', '2021-10-17 18:00:00', NOW(), NOW()),
(1, 6, 0, 2020, '第十届中国教育机器人大赛', '广东东莞 | 东莞日报、松山湖融媒体中心等主流媒体全程报道，赛事影响力持续提升。', '<h2>大赛概况</h2><p>第十届中国教育机器人大赛于 2020 年 12 月 8 日至 9 日在广东省东莞市举办。本届大赛是 ERCC 迈入双位数的里程碑，标志着大赛已进入成熟发展阶段。</p><h2>媒体关注</h2><p>本届大赛获得空前媒体关注。东莞日报在头版刊发专题报道，松山湖融媒体中心进行 48 小时不间断直播，中新网、南方日报、佛山日报等 20 余家媒体进行了报道。</p><h2>赛项优化</h2><p>本届大赛对赛项设置进行了优化调整：合并了部分相似赛项，新增了智能服务机器人赛项的雏形（当时名为"服务机器人挑战赛"），评分标准更加细化和量化。</p><h2>校企合作</h2><p>大赛组委会与东莞当地 15 家高新技术企业签署合作协议，共建"机器人教育实践基地"，为参赛学生提供实习和就业通道。</p>', '__ROOT__/static/index/images/events/event-05.jpg', 'https://www.ercc.org.cn/news5/', '2020-12-09 18:00:00', NOW(), NOW()),
(1, 5, 0, 2019, '第九届中国教育机器人大赛', '广东佛山 | 创多个"第一"，全国上千学生齐聚佛山 PK 技能，场地达到国际水准。', '<h2>大赛概况</h2><p>第九届中国教育机器人大赛于 2019 年 10 月 24 日至 25 日在广东省佛山市潭洲国际会展中心举办。本届大赛创下多个"第一"，成为 ERCC 历史上的重要一届。</p><h2>多个"第一"</h2><ul><li>首次在国际化会展中心举办，场地标准达到国际赛事水平</li><li>首次实现参赛人数突破 1000 人</li><li>首次引入企业冠名赛项（"美的杯"智能搬运赛）</li><li>首次设立海外观摩团（日本、韩国高校代表）</li></ul><h2>场馆亮点</h2><p>潭洲国际会展中心为大赛提供了 5000 平方米的专用赛场，配备了专业级灯光、音响和直播设备。赛场分为竞技区、展示区和休息区，为参赛选手和观众提供了良好的参赛体验。</p><h2>赛事回顾</h2><p>大赛期间举办了"机器人教育高峰论坛"，清华大学、东南大学、香港中文大学等高校教授就机器人教育的发展趋势进行了深入探讨。</p>', '__ROOT__/static/index/images/events/event-06.jpg', 'https://www.ercc.org.cn/news5/', '2019-10-25 18:00:00', NOW(), NOW());
